            }
            case 4: {
                ZSTD_inBuffer nullIn = { NULL, 0, 0 };
                ZSTD_outBuffer nullOut = { NULL, 0, 0 };
                size_t const ret = ZSTD_compressStream2(cctx, &nullOut, &nullIn, ZSTD_e_continue);
